  cs.minEmitBox=new BABYLON.Vector3(-.7,0,-.2);cs.maxEmitBox=new BABYLON.Vector3(.7,0,.2);
  cs.minSize=.5;cs.maxSize=1.3;cs.minLifeTime=3;cs.maxLifeTime=5.5;cs.emitRate=70;
