const displays={};
function makeDisplayTex(name,w,h){return new BABYLON.DynamicTexture(name,{width:w,height:h},scene,true);}
displays.pfdL=makeDisplayTex('pfdL',640,640);
displays.ndL=makeDisplayTex('ndL',640,640);
