const tog=(c,x,y)=>{dot(c,x,y,11,'#0a0a0a');c.strokeStyle='#c8ccd0';c.lineWidth=6;c.beginPath();c.moveTo(x,y);c.lineTo(x,y-17);c.stroke();dot(c,x,y-18,5,'#e8ecef');};

