    def(4,1,2,'WIP R',()=>AIRSYS.antiIce.wiperRight!=='OFF',()=>{AIRSYS.antiIce.wiperRight=AIRSYS.antiIce.wiperRight==='OFF'?'INT':'OFF';say('RIGHT WIPER '+AIRSYS.antiIce.wiperRight);},'RIGHT WINDSHIELD WIPER');
