    R(540,80,75,28,{label:'CLIMB / CONTINUOUS THRUST',state:()=>AP.thrustMode,act:()=>{snd('sw');AP.thrustMode=AP.thrustMode==='CLB'?'CON':'CLB';say('THRUST '+AP.thrustMode);sync(true);}});
