// Normalized fuselage coordinates: x is circumference, y runs tail -> nose.
function sideBand(g,color,width,offset=0,start=.03,end=.97){
 g.fillStyle=color;
 for(const [x,sg] of [[0,-1],[.5,1],[1,-1]])g.fillRect(x+sg*offset-width/2,start,width,end-start);
}
function rearSweep(g,color,reach=.3){g.fillStyle=color;g.beginPath();g.moveTo(0,0);for(let k=0;k<=128;k++){let x=k/128;g.lineTo(x,reach+.085*Math.sin(2*Math.PI*x));}g.lineTo(1,0);g.closePath();g.fill();}
function fern(g,c){for(const [x,sg] of [[.03,1],[.47,-1]]){g.save();g.translate(x,.13);g.scale(sg*.15,.22);stroke(g,c,.05,f=>{f.moveTo(0,0);f.quadraticCurveTo(.35,.6,1,1);});for(let i=0;i<9;i++){let t=i/9;poly(g,c,[[t*t,t],[t*t-.3*(1-t),t+.06],[t*t+.06,t+.1]]);poly(g,c,[[t*t,t],[t*t+.35*(1-t),t-.04],[t*t+.06,t+.1]]);}g.restore();}}
