const sourcePathCache=new Map();
function sourceArt(g,id,x,y,w,h,override,filter){
 const a=SOURCED_ART[id];if(!a)return;
 const b=a.bounds,k=Math.min(w/b.w,h/b.h);
 g.save();g.translate(x+(w-b.w*k)/2-b.x*k,y+(h-b.h*k)/2-b.y*k);g.scale(k,k);
 let paths=sourcePathCache.get(id);if(!paths){paths=a.paths.map(p=>new Path2D(p.d));sourcePathCache.set(id,paths);}
 a.paths.forEach((p,i)=>{
  if(filter&&!filter(p,i))return;
  let fill=override||p.fill;
  if(fill==='none')return;
  if(fill==='currentColor')fill=override||'#111';
  if(fill.startsWith('url(')){
   const stops=a.gradients[fill.slice(5,-1)];const gradient=g.createLinearGradient(0,b.y+b.h,0,b.y);
   (stops||[{offset:0,color:'#512169'},{offset:1,color:'#cf4082'}]).forEach(s=>gradient.addColorStop(s.offset,s.color));fill=gradient;
  }
  g.fillStyle=fill;g.fill(paths[i],p.rule==='evenodd'?'evenodd':'nonzero');
 });g.restore();
}
