  const CK_HIDE=/_fus|_ws$|_sw[LR]$|_strut|_wheel|_ng[SW]|_mg[SW]|c172_prop|c172_spin|cirrus_prop|cirrus_spin|cirrus_roof|cirrus_mgF/;
