      const mcx=mx+mw*.56,mcy=190;ctx.save();ctx.beginPath();ctx.rect(mx+2,10,mw-4,364);ctx.clip();ctx.translate(mcx,mcy);ctx.rotate(-(d.hdg||0)*Math.PI/180);
