      bar('RPM',.3+.7*thr,mx+14,'#17c24a');bar('MAP',.25+.6*thr,mx+54,'#17c24a');bar('FF',.15+.7*thr,mx+94,'#17c24a');bar('OIL',.55,mx+134,'#17c24a');
