    const face=(x)=>{ctx.beginPath();ctx.arc(x,cy,R,0,Math.PI*2);ctx.fillStyle='#050608';ctx.fill();ctx.lineWidth=5;ctx.strokeStyle='#8a8f98';ctx.stroke();};
