      ctx.restore();ctx.fillStyle='#ffc400';ctx.beginPath();ctx.moveTo(x,cy-8);ctx.lineTo(x-14,cy+18);ctx.lineTo(x,cy+10);ctx.lineTo(x+14,cy+18);ctx.closePath();ctx.fill();ctx.fillRect(x-3,cy-R+2,6,12);
