      const az0=Math.atan2(tmpF.z,tmpF.x);fa[0]=fa[1]=fa[2]=0;
      for(let k=-2;k<=2;k++){horizonAt(az0+k*.28,fc);fa[0]+=fc[0]/5;fa[1]+=fc[1]/5;fa[2]+=fc[2]/5;}
